beforeExample:
import org.eclipse.jface.resource.ImageDescriptor;
import org.eclipse.swt.graphics.ImageData;
import org.eclipse.swt.graphics.Point;

public class MyClass {
    private static Point fgSize;
    private ImageDescriptor descriptor;

    public void foo() {
        ImageData imageData = descriptor.getImageData();
        fgSize = new Point(imageData.width, imageData.height);
    }

    public ImageData getSomeImageData() {
        return descriptor.getImageData();
    }
}

afterExample:
import org.eclipse.jface.resource.ImageDescriptor;
import org.eclipse.swt.graphics.ImageData;
import org.eclipse.swt.graphics.Point;

public class MyClass {
    private static Point fgSize;
    private ImageDescriptor descriptor;

    public void foo() {
        ImageData imageData = descriptor.getImageData(100);
        fgSize = new Point(imageData.width, imageData.height);
    }

    public ImageData getSomeImageData() {
        return descriptor.getImageData(100);
    }
}

